from collections import defaultdict

def transform(inp, bg, dot, fillcolor):
 h,w=len(inp),len(inp[0]); ps=[(r,c) for r in range(h) for c in range(w) if inp[r][c]==dot]
 filled=set()
 # horizontal/vertical pair spans
 for i,(r,c) in enumerate(ps):
  for rr,cc in ps[i+1:]:
   dr,dc=rr-r,cc-c
   if dr==0 or dc==0:
    n=max(abs(dr),abs(dc)); sr=(dr>0)-(dr<0); sc=(dc>0)-(dc<0)
    filled.update((r+k*sr,c+k*sc) for k in range(1,n))
 # diagonals: group by line invariant r-c or r+c; fill line if 3+ points
 for keyfn in (lambda r,c:r-c,lambda r,c:r+c):
  groups=defaultdict(list)
  for r,c in ps:groups[keyfn(r,c)].append((r,c))
  for gp in groups.values():
   if len(gp)>=3:
    gp=sorted(gp)
    for (r,c),(rr,cc) in zip(gp,gp[1:]):
     dr=(rr>r)-(rr<r);dc=(cc>c)-(cc<c)
     for k in range(1,abs(rr-r)):filled.add((r+k*dr,c+k*dc))
 out=[row[:] for row in inp]
 for r,c in filled:
  if out[r][c]==bg:out[r][c]=fillcolor
 return out,filled
